def flatten(items):
    """Flatten nested lists into one flat list, keeping order."""
    out = []
    stack = [items]

    while stack:
        current = stack.pop()

        if isinstance(current, list):
            stack.extend(reversed(current))
        else:
            out.append(current)

    return out
