def shipping_order(orders):
    """The orders in the order they should ship: first come, first served."""
    incoming = JobStack()
    outgoing = JobStack()

    for o in orders:
        incoming.add(o)

    while len(incoming):
        outgoing.add(incoming.take())

    shipped = []
    while len(outgoing):
        shipped.append(outgoing.take())

    return shipped

