import re


def parse_percent(text):
    """'45%' -> 0.45"""
    if text is None:
        return None

    if isinstance(text, bool):
        return None

    if isinstance(text, (int, float)):
        return float(text) / 100.0

    if not isinstance(text, str):
        return None

    match = re.fullmatch(
        r"\s*([+-]?)\s*(\d+(?:\.\d*)?|\.\d+)\s*%?\s*",
        text
    )

    if not match:
        return None

    sign, number = match.groups()
    return float(sign + number) / 100.0
