def parse_version(text):
    """Parse a version string into a 3-tuple."""
    if text is None or not isinstance(text, str):
        return None

    s = text.strip()
    if not s:
        return None

    if s.startswith("v"):
        s = s[1:]

    if not s:
        return None

    parts = s.split(".")
    if len(parts) > 3:
        return None

    result = []
    for part in parts:
        if not part.isdigit():
            return None
        result.append(int(part))

    while len(result) < 3:
        result.append(0)

    return tuple(result)

